using System.Net;
using System.Text;
using System.Text.Json;
using FamilyVeda.Application.Agents;
using FamilyVeda.Infrastructure.Agents;
using FluentAssertions;
using Microsoft.Extensions.Options;

namespace FamilyVeda.UnitTests;

public sealed class ChatCompletionsLlmClientTests
{
    [Fact]
    public async Task ValidOutput_SendsBearerKeyAndJsonMode_ReturnsParsedValue()
    {
        var handler = new SequencedHandler([(HttpStatusCode.OK, Envelope(0.8m))]);
        var client = CreateClient(handler);

        var result = await client.GenerateStructuredAsync<MemberContextOutput>("synthetic prompt", new { }, CancellationToken.None);

        result.Value.Confidence.Should().Be(0.8m);
        result.ModelName.Should().Be("synthetic-model");
        result.InputTokens.Should().Be(3);
        result.OutputTokens.Should().Be(4);
        handler.LastAuthorization.Should().Be("Bearer test-key");
        handler.LastPath.Should().Be("/openai/v1/chat/completions");
        handler.LastBody.Should().Contain("\"json_object\"");
    }

    [Fact]
    public async Task SchemaViolation_RetriesOnce_ThenReturnsValidOutput()
    {
        var handler = new SequencedHandler([(HttpStatusCode.OK, Envelope(1.1m)), (HttpStatusCode.OK, Envelope(0.9m))]);
        var client = CreateClient(handler);

        var result = await client.GenerateStructuredAsync<MemberContextOutput>("synthetic prompt", new { }, CancellationToken.None);

        handler.Calls.Should().Be(2);
        result.Value.Confidence.Should().Be(0.9m);
    }

    [Fact]
    public async Task RateLimitedTwice_FailsClosed()
    {
        var handler = new SequencedHandler([(HttpStatusCode.TooManyRequests, "{}"), (HttpStatusCode.TooManyRequests, "{}")]);
        var client = CreateClient(handler);

        var action = () => client.GenerateStructuredAsync<MemberContextOutput>("synthetic prompt", new { }, CancellationToken.None);

        await action.Should().ThrowAsync<InvalidOperationException>();
        handler.Calls.Should().Be(2);
    }

    private static ChatCompletionsLlmClient CreateClient(HttpMessageHandler handler) =>
        new(new HttpClient(handler) { BaseAddress = new Uri("https://llm.invalid/openai/v1/") },
            Options.Create(new LlmOptions { ApiKey = "test-key", Model = "synthetic-model", TimeoutSeconds = 5 }));

    private static string Envelope(decimal confidence)
    {
        var output = JsonSerializer.Serialize(new
        {
            memberProfile = "Synthetic member profile",
            recentVitals = Array.Empty<string>(),
            episodes = Array.Empty<string>(),
            conditions = Array.Empty<string>(),
            confidence
        });
        return JsonSerializer.Serialize(new
        {
            model = "synthetic-model",
            choices = new[] { new { message = new { role = "assistant", content = output } } },
            usage = new { prompt_tokens = 3, completion_tokens = 4 }
        });
    }

    private sealed class SequencedHandler(IEnumerable<(HttpStatusCode Status, string Body)> responses) : HttpMessageHandler
    {
        private readonly Queue<(HttpStatusCode Status, string Body)> _responses = new(responses);
        public int Calls { get; private set; }
        public string? LastAuthorization { get; private set; }
        public string? LastPath { get; private set; }
        public string LastBody { get; private set; } = "";

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            Calls++;
            LastAuthorization = request.Headers.Authorization?.ToString();
            LastPath = request.RequestUri?.AbsolutePath;
            LastBody = request.Content is null ? "" : await request.Content.ReadAsStringAsync(cancellationToken);
            var (status, body) = _responses.Dequeue();
            return new HttpResponseMessage(status) { Content = new StringContent(body, Encoding.UTF8, "application/json") };
        }
    }
}
